plc_prg_impl:
(* MODBUS IN: HR0 Command word -> commands *)
StartCommand := Mb_Command.0;
StopCommand := Mb_Command.1;

(* MODBUS IN: HR1..HR2 Setpoint REAL32 (register words -> REAL memory) *)
IF Mb_Setpoint_W0 <> Mb_Setpoint_W0_prev OR Mb_Setpoint_W1 <> Mb_Setpoint_W1_prev THEN
    p_Setpoint := ADR(Setpoint);
    p_Setpoint^[0] := Mb_Setpoint_W0;
    p_Setpoint^[1] := Mb_Setpoint_W1;
    Mb_Setpoint_W0_prev := Mb_Setpoint_W0;
    Mb_Setpoint_W1_prev := Mb_Setpoint_W1;
END_IF;

(* AHU-01 : AHU_SEQ_V1 - 0 STOPPED, 1 STARTING, 2 DAMPER OPENING, 3 FAN STARTING, 4 RUNNING, 5 STOPPING, 6 DAMPER CLOSING, 9 FAULT *)
NowMs := TIME_TO_UDINT(TIME());
FanFault := FanFailure;
DamperFault := DamperFailure;
AhuAlarm := FanFailure OR DamperFailure;
IF AhuAlarm AND AhuState <> 9 THEN
    AhuState := 9;
    StateTrace := StateTrace OR 16#0200;
    StateEntryMs := NowMs;
END_IF;
CASE AhuState OF
0: (* STOPPED *)
    FanCommand := FALSE;
    FanRunning := FALSE;
    DamperCommand := FALSE;
    DamperOpen := FALSE;
    IF StartCommand AND NOT StartPrev AND NOT StopCommand THEN
        SequenceStarts := SequenceStarts + 1;
        StateTrace := 16#0002;
        AhuState := 1;
        StateEntryMs := NowMs;
    END_IF;
1: (* STARTING *)
    AhuState := 2;
    StateTrace := StateTrace OR 16#0004;
    StateEntryMs := NowMs;
2: (* DAMPER OPENING *)
    DamperCommand := TRUE;
    IF StopCommand AND NOT StopPrev THEN
        SequenceStops := SequenceStops + 1;
        AhuState := 5;
        StateTrace := StateTrace OR 16#0020;
        StateEntryMs := NowMs;
    ELSIF NowMs - StateEntryMs >= 2000 THEN
        DamperOpen := TRUE;
        AhuState := 3;
        StateTrace := StateTrace OR 16#0008;
        StateEntryMs := NowMs;
    END_IF;
3: (* FAN STARTING *)
    FanCommand := TRUE;
    IF StopCommand AND NOT StopPrev THEN
        SequenceStops := SequenceStops + 1;
        AhuState := 5;
        StateTrace := StateTrace OR 16#0020;
        StateEntryMs := NowMs;
    ELSIF NowMs - StateEntryMs >= 1000 THEN
        FanRunning := TRUE;
        AhuState := 4;
        StateTrace := StateTrace OR 16#0010;
        StateEntryMs := NowMs;
    END_IF;
4: (* RUNNING *)
    IF StopCommand AND NOT StopPrev THEN
        SequenceStops := SequenceStops + 1;
        AhuState := 5;
        StateTrace := StateTrace OR 16#0020;
        StateEntryMs := NowMs;
    END_IF;
5: (* STOPPING: fan run-down *)
    FanCommand := FALSE;
    IF NowMs - StateEntryMs >= 1000 THEN
        FanRunning := FALSE;
        AhuState := 6;
        StateTrace := StateTrace OR 16#0040;
        StateEntryMs := NowMs;
    END_IF;
6: (* DAMPER CLOSING *)
    DamperCommand := FALSE;
    IF NowMs - StateEntryMs >= 2000 THEN
        DamperOpen := FALSE;
        AhuState := 0;
        StateTrace := StateTrace OR 16#0001;
        StateEntryMs := NowMs;
    END_IF;
9: (* FAULT: safe state *)
    FanCommand := FALSE;
    FanRunning := FALSE;
    DamperCommand := FALSE;
    DamperOpen := FALSE;
    IF NOT AhuAlarm THEN
        AhuState := 0;
        StateTrace := StateTrace OR 16#0001;
        StateEntryMs := NowMs;
    END_IF;
ELSE (* unknown state value: safe fallback *)
    FanCommand := FALSE;
    FanRunning := FALSE;
    DamperCommand := FALSE;
    DamperOpen := FALSE;
    AhuState := 0;
    StateEntryMs := NowMs;
END_CASE;
StartPrev := StartCommand;
StopPrev := StopCommand;

(* HEATING - simple demo, not PID *)
IF SupplyTemp < Setpoint THEN
    HeatingValve := 100.0;
ELSE
    HeatingValve := 0.0;
END_IF;

(* MODBUS OUT: status -> IR0 Status word *)
Mb_Status := 0;
Mb_Status.0 := FanCommand;
Mb_Status.1 := FanRunning;
Mb_Status.2 := FanFault;

(* MODBUS OUT: AhuState INT16 -> IR1 *)
Mb_AhuState := INT_TO_WORD(AhuState);

(* MODBUS OUT: HeatingValve REAL32 (REAL memory -> register words) -> IR2..IR3 *)
p_HeatingValve := ADR(HeatingValve);
Mb_HeatingValve_W0 := p_HeatingValve^[0];
Mb_HeatingValve_W1 := p_HeatingValve^[1];

(* MODBUS OUT: SequenceStarts UINT16 -> IR4 *)
Mb_SequenceStarts := UINT_TO_WORD(SequenceStarts);

(* MODBUS OUT: SequenceStops UINT16 -> IR5 *)
Mb_SequenceStops := UINT_TO_WORD(SequenceStops);

(* MODBUS OUT: StateTrace WORD -> IR6 *)
Mb_StateTrace := StateTrace;

(* MODBUS OUT: SupplyTemp REAL32 (REAL memory -> register words) -> IR7..IR8 *)
p_SupplyTemp := ADR(SupplyTemp);
Mb_SupplyTemp_W0 := p_SupplyTemp^[0];
Mb_SupplyTemp_W1 := p_SupplyTemp^[1];

(* MODBUS OUT: AhuAlarm BOOL -> DI144 *)
Mb_AhuAlarm := AhuAlarm;

(* MODBUS OUT: DamperCommand BOOL -> DI145 *)
Mb_DamperCommand := DamperCommand;

(* MODBUS OUT: DamperFault BOOL -> DI146 *)
Mb_DamperFault := DamperFault;

(* MODBUS OUT: DamperOpen BOOL -> DI147 *)
Mb_DamperOpen := DamperOpen;

(* MODBUS OUT: FanRunning BOOL -> DI148 *)
Mb_FanRunning := FanRunning;

plc_prg_decl:
PROGRAM PLC_PRG
VAR
    (* Deterministic demo for AHU-SEQ: AHU-01 (AHU) *)
    StartCommand : BOOL := FALSE;
    StopCommand : BOOL := FALSE;
    FanCommand : BOOL := FALSE;
    FanRunning : BOOL := FALSE;
    FanFault : BOOL := FALSE;
    DamperCommand : BOOL := FALSE;
    DamperOpen : BOOL := FALSE;
    FanFailure : BOOL := FALSE;
    DamperFailure : BOOL := FALSE;
    DamperFault : BOOL := FALSE;
    AhuAlarm : BOOL := FALSE;
    AhuState : INT := 0;
    StateTrace : WORD := 16#0000;
    SequenceStarts : UINT := 0;
    SequenceStops : UINT := 0;
    StartPrev : BOOL := FALSE;
    StopPrev : BOOL := FALSE;
    NowMs : UDINT := 0;
    StateEntryMs : UDINT := 0;
    SupplyTemp : REAL := 21.0;
    Setpoint : REAL := 22.0;
    HeatingValve : REAL := 0.0;
    (* Modbus TCP image (16-bit words, mapped to Modbus_TCP_Server I/O) *)
    Mb_Command : WORD; (* HR0 Command: bit0=StartCommand, bit1=StopCommand *)
    Mb_Setpoint_W0 : WORD; (* HR1 Setpoint REAL32 memory word 0 *)
    Mb_Setpoint_W1 : WORD; (* HR2 Setpoint REAL32 memory word 1 *)
    p_Setpoint : POINTER TO ARRAY[0..1] OF WORD;
    Mb_Setpoint_W0_prev : WORD;
    Mb_Setpoint_W1_prev : WORD;
    Mb_Status : WORD; (* IR0 Status: bit0=FanCommand, bit1=FanRunning, bit2=FanFault *)
    Mb_AhuState : WORD; (* IR1 AhuState INT16 READ *)
    Mb_HeatingValve_W0 : WORD; (* IR2 HeatingValve REAL32 memory word 0 *)
    Mb_HeatingValve_W1 : WORD; (* IR3 HeatingValve REAL32 memory word 1 *)
    p_HeatingValve : POINTER TO ARRAY[0..1] OF WORD;
    Mb_SequenceStarts : WORD; (* IR4 SequenceStarts UINT16 READ *)
    Mb_SequenceStops : WORD; (* IR5 SequenceStops UINT16 READ *)
    Mb_StateTrace : WORD; (* IR6 StateTrace WORD READ *)
    Mb_SupplyTemp_W0 : WORD; (* IR7 SupplyTemp REAL32 memory word 0 *)
    Mb_SupplyTemp_W1 : WORD; (* IR8 SupplyTemp REAL32 memory word 1 *)
    p_SupplyTemp : POINTER TO ARRAY[0..1] OF WORD;
    Mb_AhuAlarm : BOOL; (* DI144 AhuAlarm = IR9 PLC bit 8 *)
    Mb_DamperCommand : BOOL; (* DI145 DamperCommand = IR9 PLC bit 9 *)
    Mb_DamperFault : BOOL; (* DI146 DamperFault = IR9 PLC bit 10 *)
    Mb_DamperOpen : BOOL; (* DI147 DamperOpen = IR9 PLC bit 11 *)
    Mb_FanRunning : BOOL; (* DI148 FanRunning = IR9 PLC bit 12 *)
END_VAR
